"""Request handlers."""

import re

from app.services import users

_KEY_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*):(.*)$")
_INT_RE = re.compile(r"^-?\d+$")


def _parse_value(raw: str) -> object:
    if raw in ("true", "false"):
        return raw == "true"
    if _INT_RE.match(raw):
        return int(raw)
    if len(raw) >= 2 and raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]
    return raw


def handle_parse_settings(params: dict) -> tuple[int, dict]:
    text = params.get("text")
    if not isinstance(text, str):
        return 400, {"error": "invalid settings"}

    settings: dict = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        match = _KEY_RE.match(line)
        if match is None:
            return 400, {"error": "invalid settings"}
        key, value = match.group(1), match.group(2).strip()
        if key in settings:
            return 400, {"error": "invalid settings"}
        settings[key] = _parse_value(value)
    return 200, {"settings": settings}


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user
